// @FIGURE_CODE_BEGIN
var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1200, H = 450;
draw.viewbox(0, 0, W, H);

var state = {
  mode: 'free',
  selected: 'freeTop',
  freeCustom: { x: 540, y: 315 },
  step: 0
};

var colors = {
  red: '#ff0b00',
  green: '#19d000',
  brown: '#875124',
  black: '#050505',
  faint: '#c9c9c9',
  highlight: '#ffcf33'
};

draw.rect(W, H).fill('#ffffff');

var defs = draw.defs();
var haloFilter = defs.filterWith(function (add) {
  add.gaussianBlur('SourceAlpha', 1.4).attr('result', 'blur');
  add.flood('#ffffff', 0.95).attr('result', 'white');
  add.composite('white', 'blur', 'in').attr('result', 'glow');
  add.merge(['glow', 'SourceGraphic']);
});

function lineGroup() { return draw.group(); }
var permanent = lineGroup();
var dynamic = lineGroup();
var labels = lineGroup();

function arrowLine(g, x1, y1, x2, y2, opts) {
  opts = opts || {};
  var col = opts.color || colors.black;
  var w = opts.width || 3;
  var op = opts.opacity == null ? 1 : opts.opacity;
  var line = g.line(x1, y1, x2, y2).stroke({ color: col, width: w, linecap: 'butt' }).opacity(op);
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var ah = opts.head || 13;
  var aw = opts.headWidth || 8;
  var bx = x2 - Math.cos(ang) * ah;
  var by = y2 - Math.sin(ang) * ah;
  var px = -Math.sin(ang), py = Math.cos(ang);
  var head = g.polygon([
    [x2, y2],
    [bx + px * aw, by + py * aw],
    [bx - px * aw, by - py * aw]
  ]).fill(col).opacity(op);
  return g.group().add(line).add(head);
}

function incomingArrow(g, cx, cy, ox, oy, r, opts) {
  var dx = cx - ox, dy = cy - oy;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  var ex = cx - dx / len * r;
  var ey = cy - dy / len * r;
  return arrowLine(g, ox, oy, ex, ey, opts);
}

function labelText(g, txt, x, y, size, anchor) {
  var t = g.text(txt).font({
    family: 'Arial, Helvetica, sans-serif',
    size: size,
    anchor: anchor || 'start'
  }).fill('#000000').move(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}

function drawTree() {
  var tree = permanent.group().attr('id', 'tree');
  tree.polygon([[930,285], [1015,268], [1075,445], [888,445], [905,392], [915,330]])
    .fill(colors.brown).stroke('none');
  tree.polygon([[1010,270], [1075,268], [1035,330], [985,332]])
    .fill(colors.brown).stroke('none');
  var canopy = tree.group();
  var blobs = [
    [905,215,76,72], [965,188,86,66], [1040,202,90,70],
    [1110,240,74,65], [1070,285,78,62], [975,284,90,70],
    [882,282,65,62], [928,148,60,45], [1005,142,72,46],
    [1090,178,56,42], [842,238,54,48], [880,337,55,48]
  ];
  for (var i = 0; i < blobs.length; i++) {
    canopy.ellipse(blobs[i][2] * 2, blobs[i][3] * 2)
      .center(blobs[i][0], blobs[i][1]).fill(colors.green).stroke('none');
  }
  canopy.rect(230, 110).radius(34).center(985, 235).fill(colors.green).stroke('none');
  tree.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('Visible scene object: it sends radiance into many directions.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Scene radiance', 'A scene point on the tree can contribute light along many rays. A NeRF-like representation learns how color depends on both position and viewing direction.');
    });
}

function drawCamera() {
  var cam = permanent.group().attr('id', 'camera');
  var x = 70, y = 165, w = 175, h = 250, apY = 285, gap = 32;
  cam.line(x, y, x + w, y).stroke({ color: colors.black, width: 3 });
  cam.line(x, y + h, x + w, y + h).stroke({ color: colors.black, width: 3 });
  cam.line(x, y, x, y + h).stroke({ color: colors.black, width: 3 });
  cam.line(x + w, y, x + w, apY - gap / 2).stroke({ color: colors.black, width: 3 });
  cam.line(x + w, apY + gap / 2, x + w, y + h).stroke({ color: colors.black, width: 3 });
  cam.circle(8).center(x + w, apY).fill('#ffffff').stroke({ color: colors.black, width: 1.5 });
  labelText(permanent, 'Pinhole camera', 55, 122, 30);
  cam.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip('The black box blocks most directions; the small gap is the pinhole aperture.', e); })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      setMode('camera');
      showPopup('Pinhole camera', 'Inside the camera, light is not available from every angle. Most directions are blocked, leaving only directions that pass through the pinhole.');
    });
}

function drawCrossingRays() {
  var g = permanent.group().attr('id', 'crossing-rays').opacity(0.95);
  var aperture = { x: 245, y: 285 };
  arrowLine(g, 905, 190, aperture.x + 4, aperture.y - 2, { width: 2.5, head: 11, headWidth: 7 });
  arrowLine(g, aperture.x - 3, aperture.y - 1, 105, 218, { width: 2.5, head: 11, headWidth: 7 });
  arrowLine(g, 960, 340, aperture.x + 4, aperture.y + 2, { width: 2.5, head: 11, headWidth: 7 });
  arrowLine(g, aperture.x - 3, aperture.y + 2, 103, 340, { width: 2.5, head: 11, headWidth: 7 });
}

drawTree();
drawCamera();
drawCrossingRays();

var points = {
  camTop: { x: 84, y: 215, kind: 'camera' },
  camBottom: { x: 84, y: 340, kind: 'camera' },
  freeTop: { x: 620, y: 112, kind: 'free' },
  freeBottom: { x: 540, y: 315, kind: 'free' }
};

var sampleNodes = {};

function drawSamplePoints() {
  Object.keys(points).forEach(function (id) {
    var p = points[id];
    var c = permanent.circle(24).center(p.x, p.y).fill(colors.red).stroke('none');
    sampleNodes[id] = c;
    c.css('cursor', 'pointer')
      .on('mousemove', function (e) {
        showTooltip(p.kind === 'free' ? 'Free-space sample: many directions may carry light.' : 'Inside-camera sample: only pinhole directions survive.', e);
      })
      .on('mouseleave', hideTooltip)
      .on('click', function (e) {
        e.stopPropagation();
        selectPoint(id, true);
      });
  });
}

drawSamplePoints();

function drawDenseBundle(g, cx, cy, active) {
  var rays = active ? 30 : 20;
  var inner = active ? 28 : 24;
  var outer = active ? 210 : 130;
  for (var i = 0; i < rays; i++) {
    var a = -Math.PI + i * 2 * Math.PI / rays;
    if (!active && i % 2) continue;
    var wiggle = (i % 3 - 1) * 11;
    var ox = cx + Math.cos(a) * (outer + wiggle);
    var oy = cy + Math.sin(a) * (outer * 0.82 + wiggle);
    if (ox > 830 && oy > 105 && oy < 340) ox = 830;
    incomingArrow(g, cx, cy, ox, oy, inner, {
      width: active ? 2.8 : 2.2,
      opacity: active ? 1 : 0.35,
      head: active ? 14 : 10,
      headWidth: active ? 8 : 6
    });
  }
}

function drawSparseCameraBundle(g, cx, cy, active) {
  var aperture = { x: 245, y: 285 };
  var rays = [
    { x: aperture.x - 4, y: aperture.y - 12 },
    { x: aperture.x - 4, y: aperture.y },
    { x: aperture.x - 4, y: aperture.y + 12 }
  ];
  for (var i = 0; i < rays.length; i++) {
    incomingArrow(g, cx, cy, rays[i].x, rays[i].y, 24, {
      width: active ? 3.1 : 2.1,
      opacity: active ? 1 : 0.35,
      head: 12,
      headWidth: 7
    });
  }
  if (active) {
    for (var k = 0; k < 18; k++) {
      var a = -Math.PI + k * 2 * Math.PI / 18;
      var ox = cx + Math.cos(a) * 95;
      var oy = cy + Math.sin(a) * 75;
      var blocked = !(ox > cx + 40 && Math.abs(oy - cy) < 55);
      if (blocked) {
        incomingArrow(g, cx, cy, ox, oy, 33, {
          color: colors.faint,
          width: 1.7,
          opacity: 0.38,
          head: 8,
          headWidth: 5
        });
      }
    }
  }
}

function drawAngularGlyph(g, cx, cy, mode) {
  var glyph = g.group().attr('id', 'angular-glyph');
  glyph.circle(98).center(cx, cy).fill('none').stroke({
    color: mode === 'free' ? '#222222' : '#b8b8b8',
    width: 1.2,
    dasharray: '4,5'
  }).opacity(0.75);
  var n = 28;
  for (var i = 0; i < n; i++) {
    var a = i * 2 * Math.PI / n;
    var nonzero = mode === 'free' || (Math.abs(Math.sin(a)) < 0.18 && Math.cos(a) > 0);
    var r1 = 38, r2 = nonzero ? 54 : 45;
    var x1 = cx + Math.cos(a) * r1;
    var y1 = cy + Math.sin(a) * r1;
    var x2 = cx + Math.cos(a) * r2;
    var y2 = cy + Math.sin(a) * r2;
    glyph.line(x1, y1, x2, y2).stroke({
      color: nonzero ? colors.black : colors.faint,
      width: nonzero ? 3 : 1.4,
      linecap: 'round'
    }).opacity(nonzero ? 0.95 : 0.45);
  }
  glyph.css('cursor', 'pointer')
    .on('mousemove', function (e) {
      showTooltip(mode === 'free' ? 'Angular distribution: many directions are nonzero.' : 'Angular distribution: most directions are zero or blocked.', e);
    })
    .on('mouseleave', hideTooltip)
    .on('click', function () {
      showPopup('Angular light distribution', 'The plenoptic function is not just a color at a point. It is a distribution over incoming directions, so changing position or direction can change the observed light.');
    });
}

function drawAnnotation(g, mode, cx, cy) {
  var text, tx, ty, lx, ly;
  if (mode === 'free') {
    text = 'many nonzero directions';
    tx = cx + 62;
    ty = cy - 86;
    lx = cx + 42;
    ly = cy - 36;
  } else {
    text = 'mostly zero directions';
    tx = cx + 62;
    ty = cy - 74;
    lx = cx + 38;
    ly = cy - 30;
  }
  g.line(tx - 8, ty + 24, lx, ly).stroke({ color: '#666666', width: 1.4, dasharray: '3,3' });
  var pad = 5;
  var t = labelText(g, text, tx, ty, 16);
  var box = t.bbox();
  g.rect(box.width + pad * 2, box.height + pad * 2).move(box.x - pad, box.y - pad)
    .fill({ color: '#ffffff', opacity: 0.82 }).stroke('none').back();
}

function renderDynamic() {
  dynamic.clear();
  var sel = points[state.selected];
  Object.keys(points).forEach(function (id) {
    var p = points[id];
    if (p.kind === 'free') drawDenseBundle(dynamic, p.x, p.y, state.mode === 'free' && id === state.selected);
