function selectPoint(id, popup) {
  if (!points[id]) return;
  state.selected = id;
  setMode(points[id].kind);
  if (popup) {
    showPopup(
      points[id].kind === 'free' ? 'Free-space sample' : 'Inside-camera sample',
      points[id].kind === 'free'
