    state.selected = 'freeBottom';
    setMode('free');
  }
});

function toggle_locationContext(on) {
  setMode(on ? 'camera' : 'free');
}

var demoSteps = [
  {
    title: 'Sample light in free space',
    narration: 'A red point in open space receives light from many directions. The surrounding ray bundle is dense, showing that many angular values of the plenoptic function are nonzero.',
    apply: function () { state.selected = 'freeTop'; setMode('free'); }
  },
  {
    title: 'Move the sample point',
    narration: 'Click elsewhere in the scene to relocate the sample. The angular distribution follows the point, emphasizing that the plenoptic function stores direction-dependent light at every spatial location.',
    apply: function () { state.selected = 'freeBottom'; setMode('free'); }
  },
  {
    title: 'Sample inside the pinhole camera',
    narration: 'Inside the camera, the aperture blocks most directions. Only the rays that pass through the pinhole carry intensity, so the angular distribution becomes sparse.',
    apply: function () { state.selected = 'camTop'; setMode('camera'); }
  }
];

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  demoSteps[state.step].apply();
  var n = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (n) n.textContent = demoSteps[state.step].narration;
  if (lab) lab.textContent = (state.step + 1) + '/' + demoSteps.length + ' — ' + demoSteps[state.step].title;
}

function prevStep() { applyStep(state.step - 1); }
function nextStep() { applyStep(state.step + 1); }

window.toggle_locationContext = toggle_locationContext;
window.prevStep = prevStep;
window.nextStep = nextStep;

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

