    ly = cy - 36;
  } else {
    text = 'mostly zero directions';
    tx = cx + 62;
    ty = cy - 74;
    lx = cx + 38;
    ly = cy - 30;
  }
  g.line(tx - 8, ty + 24, lx, ly).stroke({ color: '#666666', width: 1.4, dasharray: '3,3' });
  var pad = 5;
  var t = labelText(g, text, tx, ty, 16);
  var box = t.bbox();
  g.rect(box.width + pad * 2, box.height + pad * 2).move(box.x - pad, box.y - pad)
    .fill({ color: '#ffffff', opacity: 0.82 }).stroke('none').back();
}

function renderDynamic() {
  dynamic.clear();
  var sel = points[state.selected];
  Object.keys(points).forEach(function (id) {
    var p = points[id];
    if (p.kind === 'free') drawDenseBundle(dynamic, p.x, p.y, state.mode === 'free' && id === state.selected);
    if (p.kind === 'camera') drawSparseCameraBundle(dynamic, p.x, p.y, state.mode === 'camera' && id === state.selected);
  });
  dynamic.circle(42).center(sel.x, sel.y).fill('none')
    .stroke({ color: colors.highlight, width: 4 }).opacity(0.95);
  drawAngularGlyph(dynamic, sel.x, sel.y, state.mode);
  drawAnnotation(dynamic, state.mode, sel.x, sel.y);
  Object.keys(sampleNodes).forEach(function (id) {
    sampleNodes[id].front();
    sampleNodes[id].opacity(id === state.selected ? 1 : 0.82);
  });
}

function setMode(mode) {
  state.mode = mode === 'camera' ? 'camera' : 'free';
  if (state.mode === 'camera' && points[state.selected].kind !== 'camera') state.selected = 'camTop';
  if (state.mode === 'free' && points[state.selected].kind !== 'free') state.selected = 'freeTop';
  var input = document.getElementById('locationContextInput');
  var val = document.getElementById('locationContextVal');
  if (input) input.checked = state.mode === 'camera';
  if (val) val.value = state.mode === 'camera' ? 'Inside camera' : 'Free space';
  renderDynamic();
}

function selectPoint(id, popup) {
  if (!points[id]) return;
  state.selected = id;
  setMode(points[id].kind);
  if (popup) {
    showPopup(
      points[id].kind === 'free' ? 'Free-space sample' : 'Inside-camera sample',
      points[id].kind === 'free'
        ? 'At this spatial point, light can arrive from many directions. A light-field or NeRF-like representation must store how radiance varies with direction.'
        : 'At this point inside the camera, most directions are blocked by the camera body. Only directions that line up with the pinhole have nonzero incoming light.'
    );
  }
}

draw.on('click', function (e) {
  var pt = draw.point(e.clientX, e.clientY);
  var p = pt.transform(draw.node.getScreenCTM().inverse());
  if (p.x > 275 && p.x < 850 && p.y > 55 && p.y < 395) {
    points.freeBottom.x = p.x;
    points.freeBottom.y = p.y;
    sampleNodes.freeBottom.center(p.x, p.y);
    state.selected = 'freeBottom';
    setMode('free');
  }
});

function toggle_locationContext(on) {
  setMode(on ? 'camera' : 'free');
}

var demoSteps = [
  {
    title: 'Sample light in free space',
    narration: 'A red point in open space receives light from many directions. The surrounding ray bundle is dense, showing that many angular values of the plenoptic function are nonzero.',
    apply: function () { state.selected = 'freeTop'; setMode('free'); }
  },
  {
    title: 'Move the sample point',
    narration: 'Click elsewhere in the scene to relocate the sample. The angular distribution follows the point, emphasizing that the plenoptic function stores direction-dependent light at every spatial location.',
    apply: function () { state.selected = 'freeBottom'; setMode('free'); }
  },
  {
    title: 'Sample inside the pinhole camera',
    narration: 'Inside the camera, the aperture blocks most directions. Only the rays that pass through the pinhole carry intensity, so the angular distribution becomes sparse.',
    apply: function () { state.selected = 'camTop'; setMode('camera'); }
  }
];

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  demoSteps[state.step].apply();
  var n = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (n) n.textContent = demoSteps[state.step].narration;
  if (lab) lab.textContent = (state.step + 1) + '/' + demoSteps.length + ' — ' + demoSteps[state.step].title;
}

function prevStep() { applyStep(state.step - 1); }
function nextStep() { applyStep(state.step + 1); }

window.toggle_locationContext = toggle_locationContext;
window.prevStep = prevStep;
window.nextStep = nextStep;

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: The plenoptic function assigns every point in space an angular distribution of incoming light, which is dense in open space but sparse inside a pinhole camera because the aperture admits only a few ray directions.
KEY INSIGHT (what students should walk away understanding): A NeRF-like scene representation is powerful because it can be viewed as learning this position-and-direction dependent light field: light at every point, from every direction.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
