var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
var W = 1200, H = 450;
draw.viewbox(0, 0, W, H);

var colors = {
  red: '#ff0b00',
  green: '#19d000',
  brown: '#875124',
  black: '#050505',
  faint: '#bfc0c2',
  highlight: '#ffcf33'
};

var state = {
  mode: 'free',
  selected: 'freeTop',
  step: 0
};

draw.rect(W, H).fill('#ffffff');

var base = draw.group();
var baseRays = draw.group();
var dynamic = draw.group();
var labels = draw.group();
var sampleLayer = draw.group();

function pts(a) {
  return a.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}

function arrowLine(g, x1, y1, x2, y2, opts) {
  opts = opts || {};
  var col = opts.color || colors.black;
  var sw = opts.width || 3;
  var op = opts.opacity == null ? 1 : opts.opacity;
  var ag = g.group();
  ag.line(x1, y1, x2, y2).stroke({ color: col, width: sw, linecap: 'butt' }).opacity(op);
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var ah = opts.head || 12;
  var aw = opts.headWidth || 7;
  var bx = x2 - Math.cos(ang) * ah;
  var by = y2 - Math.sin(ang) * ah;
  var px = -Math.sin(ang), py = Math.cos(ang);
  ag.polygon(pts([[x2, y2], [bx + px * aw, by + py * aw], [bx - px * aw, by - py * aw]])).fill(col).opacity(op);
  return ag;
}

function incomingArrow(g, cx, cy, ox, oy, r, opts) {
  var dx = cx - ox, dy = cy - oy;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  var ex = cx - dx / len * r;
  var ey = cy - dy / len * r;
  return arrowLine(g, ox, oy, ex, ey, opts);
}

function labelText(g, txt, x, y, size, anchor) {
  var t = g.text(txt).font({
    family: 'Arial, Helvetica, sans-serif',
    size: size,
    anchor: anchor || 'start'
  }).fill('#000000').move(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 5, 'stroke-linejoin': 'round' });
  return t;
}

function addPopupHandlers(el, tip, title, body, clickFn) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function (e) {
      if (e && e.stopPropagation) e.stopPropagation();
      if (typeof clickFn === 'function') clickFn();
      showPopup(title, body);
    });
}

var camera = { x: 68, y: 160, w: 170, h: 252, apX: 238, apY: 286, gap: 34 };

function drawCamera() {
  var cam = base.group().attr('id', 'pinhole-camera');
  var x = camera.x, y = camera.y, w = camera.w, h = camera.h;
  cam.line(x, y, x + w, y).stroke({ color: colors.black, width: 3 });
  cam.line(x, y + h, x + w, y + h).stroke({ color: colors.black, width: 3 });
  cam.line(x, y, x, y + h).stroke({ color: colors.black, width: 3 });
  cam.line(x + w, y, x + w, camera.apY - camera.gap / 2).stroke({ color: colors.black, width: 3 });
  cam.line(x + w, camera.apY + camera.gap / 2, x + w, y + h).stroke({ color: colors.black, width: 3 });
  cam.circle(8).center(camera.apX, camera.apY).fill('#ffffff').stroke({ color: colors.black, width: 1.2 });
  labelText(labels, 'Pinhole camera', 53, 118, 30);
  addPopupHandlers(
    cam,
    'The camera body blocks most directions; only rays through the small aperture enter.',
    'Pinhole camera',
    'Inside the pinhole camera the plenoptic function is sparse over direction. Most incoming angles are physically blocked by the camera wall.',
    function () { setMode('camera', 'camTop'); }
  );
}

function drawTree() {
  var tree = base.group().attr('id', 'tree');
  tree.polygon(pts([[905, 445], [1075, 445], [1038, 332], [1016, 270], [956, 272], [930, 334], [914, 392]])).fill(colors.brown);
  tree.polygon(pts([[990, 330], [1086, 284], [1045, 354], [1018, 382]])).fill(colors.brown);
  tree.polygon(pts([[924, 385], [866, 360], [900, 430]])).fill(colors.brown);

  var canopy = tree.group();
  var blobs = [
    [861, 294, 58, 52], [900, 234, 72, 58], [967, 197, 87, 61],
    [1048, 196, 88, 62], [1125, 238, 78, 62], [1097, 306, 86, 64],
    [1026, 330, 88, 61], [940, 323, 84, 62], [885, 360, 60, 54],
    [962, 146, 62, 43], [1038, 144, 68, 42], [1100, 178, 56, 42],
    [832, 242, 52, 46], [1152, 285, 45, 43]
  ];
  canopy.rect(255, 126).radius(42).center(1000, 252).fill(colors.green).stroke('none');
  for (var i = 0; i < blobs.length; i++) {
    canopy.ellipse(blobs[i][2] * 2, blobs[i][3] * 2).center(blobs[i][0], blobs[i][1]).fill(colors.green).stroke('none');
  }
  addPopupHandlers(
    tree,
    'Visible scene object: its surfaces send radiance along many rays.',
    'Scene radiance',
    'The tree contributes light along many different directions. A NeRF-like model learns color as a function of both spatial position and viewing direction.',
    null
  );
}

var points = {
  camTop: { x: 82, y: 214, kind: 'camera' },
  camBottom: { x: 82, y: 340, kind: 'camera' },
  freeTop: { x: 615, y: 112, kind: 'free' },
  freeBottom: { x: 522, y: 316, kind: 'free' }
};
var sampleNodes = {};

function drawCameraRayPaths() {
  var ap = { x: camera.apX, y: camera.apY };
  var pairs = [
    { scene: [880, 190], hit: [points.camTop.x + 17, points.camTop.y + 11], bend: [ap.x + 5, ap.y - 4] },
    { scene: [940, 340], hit: [points.camBottom.x + 17, points.camBottom.y - 8], bend: [ap.x + 5, ap.y + 5] }
  ];
  for (var i = 0; i < pairs.length; i++) {
    var p = pairs[i];
    arrowLine(baseRays, p.scene[0], p.scene[1], p.bend[0], p.bend[1], { width: 2.4, head: 10, headWidth: 6, opacity: 0.95 });
    arrowLine(baseRays, p.bend[0] - 2, p.bend[1], p.hit[0], p.hit[1], { width: 2.4, head: 10, headWidth: 6, opacity: 0.95 });
  }
}

function drawStaticFreeStar(g, cx, cy, selected) {
  var angles = [];
  for (var i = 0; i < 26; i++) angles.push(-Math.PI + (i * 2 * Math.PI / 26));
  for (var j = 0; j < angles.length; j++) {
    var a = angles[j];
    var outer = selected ? 205 : 190;
    var ox = cx + Math.cos(a) * (outer + (j % 4 - 1.5) * 10);
    var oy = cy + Math.sin(a) * (outer * 0.83 + (j % 3 - 1) * 9);
    if (ox > 850 && oy > 120 && oy < 350) ox = 850;
    if (ox < 280 && oy > 150 && oy < 420) ox = 280;
    incomingArrow(g, cx, cy, ox, oy, 29, {
      width: selected ? 2.8 : 2.35,
      opacity: selected ? 1 : 0.82,
      head: selected ? 13 : 11,
      headWidth: selected ? 8 : 6.5
    });
  }
}

function drawSparseCameraBundle(g, cx, cy, selected) {
  var ap = { x: camera.apX, y: camera.apY };
  var ports = [
    [ap.x - 5, ap.y - 14],
    [ap.x - 5, ap.y],
    [ap.x - 5, ap.y + 14]
  ];
  for (var i = 0; i < ports.length; i++) {
    incomingArrow(g, cx, cy, ports[i][0], ports[i][1], 25, {
      width: selected ? 3.0 : 2.2,
      opacity: selected ? 1 : 0.55,
      head: 12,
      headWidth: 7
    });
  }
  if (selected) {
    for (var k = 0; k < 18; k++) {
      var a = -Math.PI + k * 2 * Math.PI / 18;
      var ox = cx + Math.cos(a) * 92;
      var oy = cy + Math.sin(a) * 74;
      var allowed = ox > cx + 45 && Math.abs(oy - cy) < 45;
      if (!allowed) {
        incomingArrow(g, cx, cy, ox, oy, 36, {
          color: colors.faint,
          width: 1.5,
          opacity: 0.33,
          head: 8,
          headWidth: 5
        });
      }
    }
  }
}

function drawAngularGlyph(g, cx, cy, mode) {
  var glyph = g.group().attr('id', 'angular-distribution');
  glyph.circle(100).center(cx, cy).fill('none').stroke({
    color: mode === 'free' ? '#222222' : '#a9a9a9',
    width: 1.1,
    dasharray: '4,5'
  }).opacity(0.68);
  var n = 28;
  for (var i = 0; i < n; i++) {
    var a = i * 2 * Math.PI / n;
    var open = mode === 'free' || (Math.cos(a) > 0.83 && Math.abs(Math.sin(a)) < 0.55);
    var r1 = 38, r2 = open ? 55 : 46;
    glyph.line(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1, cx + Math.cos(a) * r2, cy + Math.sin(a) * r2)
      .stroke({ color: open ? colors.black : colors.faint, width: open ? 3 : 1.3, linecap: 'round' })
      .opacity(open ? 0.95 : 0.42);
  }
  addPopupHandlers(
    glyph,
    mode === 'free' ? 'Angular distribution: many directions are nonzero.' : 'Angular distribution: most directions are zero; the aperture leaves only a few.',
    'Angular light distribution',
    'The plenoptic function stores radiance as a function of direction at a chosen point. Moving the point or entering the camera changes which directions carry light.',
    null
  );
}

function drawAnnotation(g, mode, cx, cy) {
  var text = mode === 'free' ? 'many nonzero directions' : 'mostly zero directions';
  var tx, ty, lx, ly;
  if (mode === 'free') {
    tx = cx + 60;
    ty = cy < 200 ? cy - 76 : cy - 92;
    lx = cx + 41;
    ly = cy - 33;
  } else {
    tx = cx + 74;
    ty = cy - 74;
    lx = cx + 39;
    ly = cy - 25;
  }
  g.line(tx - 8, ty + 23, lx, ly).stroke({ color: '#666666', width: 1.3, dasharray: '3,3' });
  var t = labelText(g, text, tx, ty, 15);
  var b = t.bbox();
  g.rect(b.width + 12, b.height + 8).move(b.x - 6, b.y - 4).fill({ color: '#ffffff', opacity: 0.86 }).stroke('none').back();
}

function drawSamplePoints() {
  sampleLayer.clear();
  sampleNodes = {};
  Object.keys(points).forEach(function (id) {
    var p = points[id];
    var c = sampleLayer.circle(24).center(p.x, p.y).fill(colors.red).stroke('none');
    sampleNodes[id] = c;
    addPopupHandlers(
      c,
      p.kind === 'free' ? 'Free-space sample: many incoming directions may carry light.' : 'Inside-camera sample: only pinhole directions carry light.',
      p.kind === 'free' ? 'Free-space sample' : 'Inside-camera sample',
      p.kind === 'free'
        ? 'At this point in open space, light can arrive from many directions. The dense ray bundle represents many nonzero angular values of the plenoptic function.'
        : 'At this point inside the camera, the camera body blocks most directions. Only directions that pass through the aperture remain nonzero.',
      function () { selectPoint(id, false); }
    );
  });
}

function renderDynamic() {
  dynamic.clear();

  drawStaticFreeStar(dynamic, points.freeTop.x, points.freeTop.y, state.mode === 'free' && state.selected === 'freeTop');
  drawStaticFreeStar(dynamic, points.freeBottom.x, points.freeBottom.y, state.mode === 'free' && state.selected === 'freeBottom');
  drawSparseCameraBundle(dynamic, points.camTop.x, points.camTop.y, state.mode === 'camera' && state.selected === 'camTop');
  drawSparseCameraBundle(dynamic, points.camBottom.x, points.camBottom.y, state.mode === 'camera' && state.selected === 'camBottom');

  var sel = points[state.selected];
  dynamic.circle(42).center(sel.x, sel.y).fill('none')
    .stroke({ color: colors.highlight, width: 4 }).opacity(0.95);
  drawAngularGlyph(dynamic, sel.x, sel.y, state.mode);
  drawAnnotation(dynamic, state.mode, sel.x, sel.y);

  sampleLayer.front();
  Object.keys(sampleNodes).forEach(function (id) {
    sampleNodes[id].opacity(id === state.selected ? 1 : 0.9);
  });
  labels.front();
}

function setMode(mode, preferredPoint) {
  state.mode = mode === 'camera' ? 'camera' : 'free';
  if (preferredPoint && points[preferredPoint] && points[preferredPoint].kind === state.mode) {
    state.selected = preferredPoint;
  } else if (points[state.selected].kind !== state.mode) {
    state.selected = state.mode === 'camera' ? 'camTop' : 'freeTop';
  }
  var input = document.getElementById('locationContextInput');
  var val = document.getElementById('locationContextVal');
  if (input) input.checked = state.mode === 'camera';
  if (val) val.value = state.mode === 'camera' ? 'Inside camera' : 'Free space';
  renderDynamic();
}

function selectPoint(id, quiet) {
  if (!points[id]) return;
  state.selected = id;
  setMode(points[id].kind, id);
  if (!quiet) return;
}

function toggle_locationContext(on) {
  setMode(on ? 'camera' : 'free');
}

draw.on('click', function (e) {
  var p = draw.point(e.clientX, e.clientY).transform(draw.node.getScreenCTM().inverse());
  if (p.x > 285 && p.x < 850 && p.y > 55 && p.y < 395) {
    points.freeBottom.x = p.x;
    points.freeBottom.y = p.y;
    state.selected = 'freeBottom';
    drawSamplePoints();
    setMode('free', 'freeBottom');
    showPopup('Moved sample point', 'The red sample moved to a new spatial location. The angular distribution follows it, because the plenoptic function is defined at every point in space.');
  }
});

var demoSteps = [
  {
    title: 'Sample light in free space',
    narration: 'A red point in open space receives light from many directions. The surrounding ray bundle is dense, showing that many angular values of the plenoptic function are nonzero.',
    apply: function () { setMode('free', 'freeTop'); }
  },
  {
    title: 'Move the sample point',
    narration: 'Click elsewhere in the scene to relocate the sample. The angular distribution follows the point, emphasizing that the plenoptic function stores direction-dependent light at every spatial location.',
    apply: function () { setMode('free', 'freeBottom'); }
  },
  {
    title: 'Sample inside the pinhole camera',
    narration: 'Inside the camera, the aperture blocks most directions. Only the rays that pass through the pinhole carry intensity, so the angular distribution becomes sparse.',
    apply: function () { setMode('camera', 'camTop'); }
  }
];

function applyStep(i) {
  state.step = Math.max(0, Math.min(demoSteps.length - 1, i));
  demoSteps[state.step].apply();
  var n = document.getElementById('demoNarration');
  var lab = document.getElementById('stepLabel');
  if (n) n.textContent = demoSteps[state.step].narration;
  if (lab) lab.textContent = (state.step + 1) + '/' + demoSteps.length + ' — ' + demoSteps[state.step].title;
}

function prevStep() { applyStep(state.step - 1); }
function nextStep() { applyStep(state.step + 1); }

drawTree();
drawCamera();
drawCameraRayPaths();
drawSamplePoints();

window.toggle_locationContext = toggle_locationContext;
window.prevStep = prevStep;
window.nextStep = nextStep;

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

