  brown: '#865322',
  black: '#050505',
  gray: '#b7b7b7',
  highlight: '#ffcf33'
};

draw.rect(W, H).fill('#ffffff');

var treeLayer = draw.group();
var rayLayer = draw.group();
var cameraLayer = draw.group();
var pointLayer = draw.group();
var overlayLayer = draw.group();
var labelLayer = draw.group();

var camera = {
  x: 260,
  y: 585,
