  apertureX: 820,
  apertureY: 940,
  apertureGap: 86
};

var points = {
  camTop: { x: 305, y: 690, kind: 'camera' },
  camBottom: { x: 305, y: 1085, kind: 'camera' },
  freeTop: { x: 2020, y: 390, kind: 'free' },
  freeBottom: { x: 1645, y: 1045, kind: 'free' }
};

var state = {
  mode: 'free',
  selected: null,
  explain: false,
  step: 0
};

var pointNodes = {};

function pts(a) {
  return a.map(function (p) { return p[0] + ',' + p[1]; }).join(' ');
}

function arrowLine(g, x1, y1, x2, y2, opts) {
  opts = opts || {};
  var col = opts.color || colors.black;
  var sw = opts.width || 7;
  var op = opts.opacity == null ? 1 : opts.opacity;
  var ag = g.group();
  ag.line(x1, y1, x2, y2).stroke({ color: col, width: sw, linecap: 'butt' }).opacity(op);
  var ang = Math.atan2(y2 - y1, x2 - x1);
  var ah = opts.head || 42;
  var aw = opts.headWidth || 24;
  var bx = x2 - Math.cos(ang) * ah;
  var by = y2 - Math.sin(ang) * ah;
  var px = -Math.sin(ang), py = Math.cos(ang);
  ag.polygon(pts([[x2, y2], [bx + px * aw, by + py * aw], [bx - px * aw, by - py * aw]])).fill(col).opacity(op);
  return ag;
}

function incomingArrowToPoint(g, cx, cy, ox, oy, stopR, opts) {
  var dx = ox - cx, dy = oy - cy;
  var len = Math.sqrt(dx * dx + dy * dy) || 1;
  var ex = cx + dx / len * stopR;
  var ey = cy + dy / len * stopR;
  return arrowLine(g, ox, oy, ex, ey, opts);
}

function labelText(g, txt, x, y, size, anchor) {
  var t = g.text(txt).font({
    family: 'Arial, Helvetica, sans-serif',
    size: size,
    anchor: anchor || 'start'
  }).fill('#000000').move(x, y);
  t.attr({ 'paint-order': 'stroke', stroke: '#ffffff', 'stroke-width': 7, 'stroke-linejoin': 'round' });
  return t;
}

function addPopupHandlers(el, tip, title, body, clickFn) {
  el.css('cursor', 'pointer')
    .on('mousemove', function (e) { showTooltip(tip, e); })
    .on('mouseleave', function () { hideTooltip(); })
    .on('click', function (e) {
      if (e && e.stopPropagation) e.stopPropagation();
      if (typeof clickFn === 'function') clickFn();
      showPopup(title, body);
    });
}

function drawTree() {
  treeLayer.clear();
  var trunk = treeLayer.group();
  trunk.path(
    'M3260 695 ' +
    'C3330 880 3340 1130 3245 1420 ' +
    'L3208 1536 L3895 1536 ' +
    'C3810 1340 3760 1120 3800 855 ' +
    'C3900 790 3970 700 3998 612 ' +
    'L3835 608 ' +
    'C3770 705 3695 765 3605 790 ' +
    'C3520 750 3460 700 3415 620 Z'
  ).fill(colors.brown).stroke('none');

  var canopy = treeLayer.group();
  canopy.rect(1010, 450).radius(120).move(2880, 280).fill(colors.green).stroke('none');
  var blobs = [
    [3015, 405, 205, 190], [3205, 300, 240, 165], [3440, 280, 250, 175],
    [3690, 300, 240, 170], [3900, 405, 230, 190], [3995, 565, 210, 185],
    [3845, 695, 260, 185], [3590, 740, 275, 185], [3335, 720, 285, 195],
    [3075, 665, 245, 190], [2985, 535, 220, 180], [3495, 450, 310, 210],
