function drawCamera() {
  cameraLayer.clear();
  labelLayer.clear();

  var x = camera.x, y = camera.y, w = camera.w, h = camera.h;
  var apY = camera.apertureY, gap = camera.apertureGap;
  var cam = cameraLayer.group();

  cam.line(x, y, x + w, y).stroke({ color: colors.black, width: 8 });
  cam.line(x, y + h, x + w, y + h).stroke({ color: colors.black, width: 8 });
  cam.line(x, y, x, y + h).stroke({ color: colors.black, width: 8 });
  cam.line(x + w, y, x + w, apY - gap / 2).stroke({ color: colors.black, width: 8 });
  cam.line(x + w, apY + gap / 2, x + w, y + h).stroke({ color: colors.black, width: 8 });

  labelText(labelLayer, 'Pinhole camera', 210, 480, 96);

  addPopupHandlers(
    cam,
    'The box blocks most directions; only rays through the small aperture enter.',
    'Pinhole camera',
    'A pinhole camera admits only a small set of directions through its aperture. That is why the angular light distribution inside the camera is sparse compared with open space.',
    function () { inspectPoint('camTop'); }
  );
}

function drawFreeStar(cx, cy, variant) {
  var count = 34;
  for (var i = 0; i < count; i++) {
    var a = -Math.PI + i * 2 * Math.PI / count;
    var jitter = (variant === 'top' ? [0, 18, -12, 30, -22] : [20, -16, 8, -25, 12])[i % 5];
    var rx = variant === 'top' ? 760 : 660;
    var ry = variant === 'top' ? 690 : 710;
    var ox = cx + Math.cos(a) * (rx + jitter);
    var oy = cy + Math.sin(a) * (ry + jitter * 0.5);

    if (variant === 'top') {
      if (ox > 2450 && oy > 260 && oy < 670) ox = 2450;
      if (ox < 1230 && oy > 130 && oy < 620) ox = 1230;
    } else {
      if (ox > 2545 && oy > 795 && oy < 1330) ox = 2545;
      if (ox < 1220 && oy > 760 && oy < 1280) ox = 1220;
    }
    oy = Math.max(30, Math.min(H - 30, oy));

    incomingArrowToPoint(rayLayer, cx, cy, ox, oy, 78, {
      width: 7,
      head: 44,
      headWidth: 25,
      opacity: 1
    });
  }
}

function drawCameraRayPaths() {
  var apx = camera.apertureX, apy = camera.apertureY;

  var sceneUpper = [2895, 515];
  var sceneLower = [2765, 1040];

  arrowLine(rayLayer, sceneUpper[0], sceneUpper[1], apx + 12, apy - 12, {
    width: 7,
    head: 38,
    headWidth: 22
  });
  arrowLine(rayLayer, apx - 4, apy - 12, points.camBottom.x + 80, points.camBottom.y - 12, {
    width: 7,
    head: 38,
    headWidth: 22
  });

  arrowLine(rayLayer, sceneLower[0], sceneLower[1], apx + 12, apy + 12, {
    width: 7,
    head: 38,
    headWidth: 22
  });
  arrowLine(rayLayer, apx - 4, apy + 12, points.camTop.x + 80, points.camTop.y + 2, {
    width: 7,
    head: 38,
    headWidth: 22
  });

  rayLayer.circle(15).center(apx, apy).fill('#ffffff').stroke({ color: colors.black, width: 4 });
}

function redrawRays() {
  rayLayer.clear();
  drawFreeStar(points.freeTop.x, points.freeTop.y, 'top');
  drawFreeStar(points.freeBottom.x, points.freeBottom.y, 'bottom');
  drawCameraRayPaths();
}

function drawPoints() {
  pointLayer.clear();
  pointNodes = {};
  Object.keys(points).forEach(function (id) {
    var p = points[id];
    var c = pointLayer.circle(76).center(p.x, p.y).fill(colors.red).stroke('none');
    pointNodes[id] = c;
    addPopupHandlers(
      c,
      p.kind === 'free'
        ? 'Free-space sample: many incoming directions can carry light.'
        : 'Inside-camera sample: only aperture directions carry light.',
      p.kind === 'free' ? 'Free-space sample' : 'Inside-camera sample',
      p.kind === 'free'
        ? 'At a point in open space, the plenoptic function can have nonzero radiance over many directions. The dense starburst is a visual shorthand for that rich angular distribution.'
        : 'Inside a pinhole camera, most directions are blocked by the camera body. Only directions that pass through the aperture remain nonzero.',
      function () { inspectPoint(id); }
    );
  });
}

function drawAngularGlyph(cx, cy, mode) {
  var glyph = overlayLayer.group();
  glyph.circle(164).center(cx, cy).fill('none')
    .stroke({ color: mode === 'free' ? '#111111' : '#888888', width: 4, dasharray: '12,11' })
    .opacity(0.85);

  var n = 32;
  for (var i = 0; i < n; i++) {
    var a = i * 2 * Math.PI / n;
    var open = mode === 'free' || (Math.cos(a) > 0.88 && Math.abs(Math.sin(a)) < 0.45);
    var r1 = 82;
    var r2 = open ? 128 : 106;
    glyph.line(cx + Math.cos(a) * r1, cy + Math.sin(a) * r1, cx + Math.cos(a) * r2, cy + Math.sin(a) * r2)
      .stroke({ color: open ? colors.black : colors.gray, width: open ? 7 : 3, linecap: 'round' })
      .opacity(open ? 0.95 : 0.45);
  }

  addPopupHandlers(
    glyph,
    mode === 'free' ? 'Many angular directions are nonzero here.' : 'Most directions are zero; the aperture leaves only a few.',
    'Angular light distribution',
    'The plenoptic function is evaluated at a spatial point and over viewing direction. The glyph summarizes which directions carry light at the selected point.',
    null
  );
}

function drawAnnotation(cx, cy, mode) {
  var txt = mode === 'free' ? 'many nonzero directions' : 'mostly zero directions';
  var tx, ty, lx, ly;
  if (mode === 'free') {
    tx = cx + 160;
    ty = cy < 700 ? cy - 120 : cy - 150;
    lx = cx + 118;
    ly = cy - 74;
  } else {
    tx = camera.x + camera.w + 120;
    ty = cy < 850 ? cy - 90 : cy + 55;
    lx = cx + 70;
    ly = cy - 10;
  }

  var t = labelText(overlayLayer, txt, tx, ty, 34);
  var b = t.bbox();
  overlayLayer.rect(b.width + 28, b.height + 18)
    .move(b.x - 14, b.y - 9)
    .fill({ color: '#ffffff', opacity: 0.88 })
    .stroke('none')
    .back();
  overlayLayer.line(tx - 12, ty + 32, lx, ly)
    .stroke({ color: '#555555', width: 4, dasharray: '10,10' })
    .back();
}

function renderOverlay() {
  overlayLayer.clear();
  if (!state.explain || !state.selected || !points[state.selected]) return;

  var p = points[state.selected];
  overlayLayer.circle(116).center(p.x, p.y).fill('none')
    .stroke({ color: colors.highlight, width: 10 })
    .opacity(0.95);

  drawAngularGlyph(p.x, p.y, p.kind);
  drawAnnotation(p.x, p.y, p.kind);

  pointLayer.front();
  overlayLayer.front();
}

function setContext(mode, selected, explain) {
  state.mode = mode === 'camera' ? 'camera' : 'free';
  if (selected && points[selected] && points[selected].kind === state.mode) {
    state.selected = selected;
  } else if (!state.selected || !points[state.selected] || points[state.selected].kind !== state.mode) {
    state.selected = state.mode === 'camera' ? 'camTop' : 'freeTop';
  }
  if (typeof explain === 'boolean') state.explain = explain;

  var input = document.getElementById('locationContextInput');
  var val = document.getElementById('locationContextVal');
  if (input) input.checked = state.mode === 'camera';
  if (val) {
    val.value = state.mode === 'camera' ? 'Inside camera' : 'Free space';
    val.textContent = state.mode === 'camera' ? 'Inside camera' : 'Free space';
  }
  renderOverlay();
}

function inspectPoint(id) {
  if (!points[id]) return;
  setContext(points[id].kind, id, true);
}

function toggle_locationContext(on) {
  setContext(on ? 'camera' : 'free', on ? 'camTop' : 'freeTop', true);
}

draw.on('click', function (e) {
  var inv = draw.node.getScreenCTM().inverse();
  var p = draw.point(e.clientX, e.clientY).transform(inv);

